// Name the things that were created without a name.
//
// "Too many rooms, documents and office items, widgets and desks are untitled.
// Make it so making a title is required, where generated by AI it's given, and
// where it exists elsewhere inherit the content and choose a title using a
// lowest model of AI based on its content. Super low credit usage for that
// extreme case. Retrospectively run this on start up."
//
// Three rules shape the whole thing.
//
// FREE FIRST, AND ALMOST ALWAYS. `shared/titles.ts` derives a name from what
// the item already contains — a heading, the first real line, a filename, a
// URL. That is deterministic, costs nothing and handles the large majority.
// The model is the last resort for items that have content but no sentence
// worth lifting: a sheet of figures, a diagram of boxes, a slide of fragments.
//
// CHEAPEST MODEL, ONE CALL, HARD CAP. The remainder go into a SINGLE batched
// request at the `title_backfill` purpose, which routes to Haiku — and routes
// through `resolveModel` rather than naming an id, so when the Haiku constant
// is bumped this follows automatically. The batch is capped at MAX_AI_ITEMS
// and each item's content is trimmed to SNIPPET_CHARS, so the worst case on a
// first run over a large workspace is bounded and small. If a user somehow has
// a thousand untitled items, they get the first MAX_AI_ITEMS this launch and
// the rest next launch; nobody gets a surprise bill.
//
// NEVER INVENT, AND NEVER RE-ASK. An item with no content is left untitled —
// a confident wrong name is worse than a visibly missing one, because the
// user stops looking inside. And every item considered is recorded in
// `title_backfill_log` whether or not it got a name, so a launch never pays
// twice for the same empty note. A user editing the title later is untouched
// by any of this; the log only stops US asking again.

import { getDb } from './db/database'
import { resolveAnthropicKey } from './settingsStore'
import { getModelClient } from './ai/modelClient'
import { resolveModel } from './ai/modelRouting'
import { deriveTitle, isUntitled, textFromBody } from '@shared/titles'
import { deriveWidgetFileTitle, parseWidgetFileBody, widgetFileTypeLabel } from '@shared/widgetFiles'
import { widgetFileBodyToText } from '@shared/widgetText'
import { mainWidgetResolvers } from './ai/widgetSummary'
import { setWidgetFileTitle } from './db/widgetFiles'
import type { WidgetKind } from '@shared/types'

/** The most items one launch will send to a model. */
const MAX_AI_ITEMS = 40
/** How much of an item's content the model is shown. */
const SNIPPET_CHARS = 400
/** Output ceiling — 40 short titles plus JSON scaffolding fits comfortably. */
const MAX_OUTPUT_TOKENS = 1200

export interface BackfillSummary {
  /** Untitled items found this run. */
  found: number
  /** Named from their own content, free. */
  derived: number
  /** Named by the model. */
  byModel: number
  /** Had nothing to go on, left untitled. */
  skipped: number
  /** True when a model call was actually made. */
  usedModel: boolean
}

interface Candidate {
  table: 'nodes' | 'documents' | 'widgets'
  id: string
  /** What the user calls this, for the model's prompt and for logging. */
  noun: string
  /** Raw text to derive from. */
  text: string
  /**
   * Set for a WIDGET FILE (documents.doc_type 'widget'): its kind and content,
   * so the free pass can use the kind's own naming rule (a table's header and
   * row count, a task list's first task) before the generic text rule. Its
   * title is written through db/widgetFiles so the name reaches every desk
   * instance and is marked as ours, never the user's. See docs/widget-files.md.
   */
  widgetFile?: { kind: WidgetKind; content: string }
}

/** The DB-backed widget resolvers, or none if they cannot be built. */
function safeResolvers(): ReturnType<typeof mainWidgetResolvers> {
  try {
    return mainWidgetResolvers()
  } catch {
    return {}
  }
}

/** Remember what we have already considered, so a launch never pays twice. */
function ensureLog(): void {
  getDb().exec(`
    CREATE TABLE IF NOT EXISTS title_backfill_log (
      item_table TEXT NOT NULL,
      item_id TEXT NOT NULL,
      -- 'derived' | 'model' | 'no-content'. Kept so a later run can tell a
      -- genuinely empty item from one we simply have not reached yet.
      outcome TEXT NOT NULL,
      at INTEGER NOT NULL,
      PRIMARY KEY (item_table, item_id)
    );
  `)
}

function alreadySeen(): Set<string> {
  ensureLog()
  const rows = getDb()
    .prepare('SELECT item_table, item_id FROM title_backfill_log')
    .all() as Array<{ item_table: string; item_id: string }>
  return new Set(rows.map((r) => `${r.item_table}:${r.item_id}`))
}

function noteSeen(table: string, id: string, outcome: string): void {
  getDb()
    .prepare(
      `INSERT INTO title_backfill_log (item_table, item_id, outcome, at)
       VALUES (@table, @id, @outcome, @at)
       ON CONFLICT(item_table, item_id) DO UPDATE SET outcome = excluded.outcome, at = excluded.at`
    )
    .run({ table, id, outcome, at: Date.now() })
}

/**
 * Everything currently lacking a real name.
 *
 * Note this reads across ALL orgs deliberately: it is a repair pass over the
 * user's own local database, not a user-facing listing, and leaving another
 * org's desks untitled because they were not active at launch would mean the
 * repair never reaches them.
 */
function findUntitled(seen: Set<string>): Candidate[] {
  const db = getDb()
  const out: Candidate[] = []

  const nodes = db
    .prepare("SELECT id, kind, title, description FROM nodes WHERE kind IN ('task','folder','work_item')")
    .all() as Array<{ id: string; kind: string; title: string; description: string }>
  for (const n of nodes) {
    if (!isUntitled(n.title)) continue
    if (seen.has(`nodes:${n.id}`)) continue
    out.push({
      table: 'nodes',
      id: n.id,
      noun: n.kind === 'task' ? 'desk' : n.kind === 'folder' ? 'room' : 'work item',
      text: n.description ?? ''
    })
  }

  const docs = db
    .prepare('SELECT id, doc_type, title, body FROM documents WHERE archived = 0')
    .all() as Array<{ id: string; doc_type: string; title: string; body: string }>
  const resolvers = safeResolvers()
  for (const d of docs) {
    if (d.doc_type === 'widget') {
      // A widget file always HAS a title — a dated placeholder rather than
      // "Untitled" — so isUntitled cannot find it. Its body says whether that
      // title is still the placeholder; nothing else is a candidate, so a name
      // the user typed (or one already derived) is never looked at again.
      const body = parseWidgetFileBody(d.body)
      if (!body || body.titleSource !== 'placeholder') continue
      if (seen.has(`documents:${d.id}`)) continue
      out.push({
        table: 'documents',
        id: d.id,
        noun: `${widgetFileTypeLabel(body.kind).toLowerCase()} work widget`,
        text: widgetFileBodyToText(body, '', resolvers).replace(/^\(.*\)$/, ''),
        widgetFile: { kind: body.kind, content: body.content }
      })
      continue
    }
    if (!isUntitled(d.title)) continue
    if (seen.has(`documents:${d.id}`)) continue
    out.push({
      table: 'documents',
      id: d.id,
      noun: d.doc_type === 'sheet' ? 'spreadsheet' : d.doc_type === 'slides' ? 'slide deck' : d.doc_type,
      text: textFromBody(d.body)
    })
  }

  const widgets = db
    .prepare('SELECT id, kind, title, content FROM widgets')
    .all() as Array<{ id: string; kind: string; title: string; content: string }>
  for (const w of widgets) {
    if (!isUntitled(w.title)) continue
    if (seen.has(`widgets:${w.id}`)) continue
    out.push({
      table: 'widgets',
      id: w.id,
      noun: `${w.kind} work widget`,
      text: textFromBody(w.content)
    })
  }

  return out
}

function writeTitle(table: Candidate['table'], id: string, title: string, c?: Candidate): void {
  if (c?.widgetFile) {
    // Through the widget-file store: it fans the name out to the desk
    // instances and records it as generated, and it refuses a user's name.
    setWidgetFileTitle(id, title, 'derived')
    return
  }
  getDb()
    .prepare(`UPDATE ${table} SET title = @title, updated_at = @now WHERE id = @id`)
    .run({ title, id, now: Date.now() })
}

/**
 * Name everything that can be named, and log everything that was considered.
 *
 * Safe to call on every launch: the log makes repeat runs cheap, and a run
 * that fails part-way simply leaves the rest for next time.
 */
export async function runTitleBackfill(
  opts: { allowModel?: boolean } = {}
): Promise<BackfillSummary> {
  const summary: BackfillSummary = {
    found: 0,
    derived: 0,
    byModel: 0,
    skipped: 0,
    usedModel: false
  }

  let candidates: Candidate[]
  try {
    candidates = findUntitled(alreadySeen())
  } catch {
    // A repair pass must never be the reason the app fails to start.
    return summary
  }
  summary.found = candidates.length
  if (candidates.length === 0) return summary

  // ── Pass 1: free ──────────────────────────────────────────────────────────
  const needsModel: Candidate[] = []
  for (const c of candidates) {
    let name: string | null = null
    try {
      // A widget file's own rule first (a table names itself from its header
      // and row count), then the same free text rule as everything else.
      name =
        (c.widgetFile ? deriveWidgetFileTitle(c.widgetFile.kind, c.widgetFile.content, safeResolvers()) : null) ??
        deriveTitle({ text: c.text })
    } catch {
      name = null
    }
    if (name) {
      try {
        writeTitle(c.table, c.id, name, c)
        noteSeen(c.table, c.id, 'derived')
        summary.derived++
      } catch {
        /* leave it for the next launch */
      }
      continue
    }
    // Only worth a model call if there is content to reason about. An empty
    // note cannot be named by anyone without inventing its subject.
    if (c.text.trim().length >= 12) needsModel.push(c)
    else if (c.widgetFile) {
      // An empty widget file is not logged: it is usually brand new, and the
      // content it is about to get should still be able to name it here.
      summary.skipped++
    } else {
      noteSeen(c.table, c.id, 'no-content')
      summary.skipped++
    }
  }

  if (needsModel.length === 0) return summary

  // ── Pass 2: one cheap call for the remainder ──────────────────────────────
  // Only with the person's say-so (Background AI tasks, backgroundAiGate.ts):
  // this pass sends item content to a model without a click. Not logged as
  // seen, so turning the switch on names them at the next launch.
  if (opts.allowModel === false) {
    summary.skipped += needsModel.length
    return summary
  }
  const key = resolveAnthropicKey()
  if (!key) {
    // No key configured. Leave them for a launch that has one rather than
    // logging them as hopeless.
    summary.skipped += needsModel.length
    return summary
  }

  const batch = needsModel.slice(0, MAX_AI_ITEMS)
  const items = batch.map((c, i) => ({
    i,
    kind: c.noun,
    content: c.text.replace(/\s+/g, ' ').trim().slice(0, SNIPPET_CHARS)
  }))

  try {
    const client = getModelClient(key)
    const resp = await client.messages.create({
      model: resolveModel('title_backfill'),
      max_tokens: MAX_OUTPUT_TOKENS,
      system:
        'You name documents from their content. For each item you are given, reply with a ' +
        'short title: 2 to 6 words, sentence case, naming what the item IS ABOUT. Do not ' +
        'describe the format ("a spreadsheet of..."), do not add quotes, do not invent a ' +
        'subject that is not in the content. If an item has nothing substantive to name, ' +
        'return an empty string for it. Reply with JSON only, no prose: ' +
        '{"titles":[{"i":0,"title":"..."}]}',
      messages: [{ role: 'user', content: JSON.stringify({ items }) }]
    })
    summary.usedModel = true

    const text = resp.content
      .filter((b): b is { type: 'text'; text: string } => b.type === 'text')
      .map((b) => b.text)
      .join('')
      .trim()
    const parsed = JSON.parse(text.replace(/^```(?:json)?\s*|\s*```$/g, '')) as {
      titles?: Array<{ i?: number; title?: string }>
    }

    const byIndex = new Map<number, string>()
    for (const t of parsed.titles ?? []) {
      if (typeof t?.i !== 'number' || typeof t?.title !== 'string') continue
      const clean = t.title.trim().replace(/^["']|["']$/g, '')
      // The model is held to the same bar as the free path: a name it returns
      // that is itself a placeholder is not an answer.
      if (clean && !isUntitled(clean)) byIndex.set(t.i, clean.slice(0, 60))
    }

    for (let i = 0; i < batch.length; i++) {
      const c = batch[i]
      const name = byIndex.get(i)
      if (name) {
        if (c.widgetFile) setWidgetFileTitle(c.id, name, 'model')
        else writeTitle(c.table, c.id, name)
        noteSeen(c.table, c.id, 'model')
        summary.byModel++
      } else {
        noteSeen(c.table, c.id, 'no-content')
        summary.skipped++
      }
    }
  } catch {
    // Offline, no credit, a malformed reply — all the same outcome: the items
    // stay untitled and unlogged, and the next launch tries again. Nothing is
    // written on a failed parse, so a bad response cannot rename anything.
    summary.skipped += batch.length
  }

  return summary
}
